// === Tab: mySketch ===
const WIDTH = 920;
const HEIGHT = 690;
let startX;
let startY;
let bgImage;
let p;
let particles = [];

// Farbpaletten
codingtrain = [[255, 0, 0], [255, 128, 0], [255, 255, 0] , [0, 240, 0],
               [0, 240, 240], [0, 120, 255], [50, 50, 255], [255, 0, 255]]

class Particle {

    constructor(x, y) {
        this.pos = createVector(x, y);
        this.acc = createVector(0, 0.05);
        this.vel = createVector(random(-2.0, 2.0), random(-2.0, 0.0));
        this.c = random(codingtrain);
        this.lifespan = 255.0;
        this.d = random(5, 30);
         }

    update() {
        this.vel.add(this.acc);
        this.pos.add(this.vel);
        this.lifespan -= random(1, 1.5);
    }

    display() {
        stroke(0, this.lifespan);
        let fillColor = color(this.c[0], this.c[1], this.c[2], this.lifespan);
        fill(fillColor);
        circle(this.pos.x, this.pos.y, this.d);
    }

    isNotAlive() {
        if (this.lifespan <= 0) {
            return(true);
        } else {
            return(false);
        }
    }
}

class RectParticle extends Particle {

    constructor(x, y) {
        super(x, y);
        rectMode(CENTER);
        this.rota = PI/3;
    }

    display() {
        stroke(0, this.lifespan);
        var fillColor = color(this.c[0], this.c[1], this.c[2], this.lifespan);
        fill(fillColor);
        push();
        translate(this.pos.x, this.pos.y);
        rotate(this.rota);
        rect(0, 0, this.d, this.d);
        pop();
        this.rota += random(0.02, .10);
    }
}

function preload() {
  //bgImage = loadImage("https://openprocessing.org/sketch/2204075/files/bgsmallvillage.jpg");
	bgImage = loadImage("https://openprocessing.org/sketch/2204075/files/IMG_6667.JPG");
}

function setup() {
  createCanvas(WIDTH, HEIGHT);
  startX = width/2;
  startY = 70;
}

function draw() {
  image(bgImage, 0,0,width*1.4,height)
  let change = random(10);
  if (change <= 5) {
    p = new Particle(startX, startY);
  } else {
    p = new RectParticle(startX, startY);
  }
  particles.push(p)
   for (let i = 0; i < particles.length; i++) {
    particles[i].update();
    particles[i].display();
    if (particles[i].isNotAlive()) {
      particles.splice(i, 1);
     }
  }
}

let lapse = 0;    // mouse timer
function mousePressed(){
// prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() +      ".jpg");
    lapse = millis();
  }
}

